CREATE TABLE "AthleteDiscovery" (
  "userId" TEXT NOT NULL PRIMARY KEY,
  "version" BIGINT NOT NULL,
  "draft" JSONB NOT NULL,
  "configuration" JSONB NOT NULL,
  "phase" TEXT NOT NULL DEFAULT 'CONSENTS',
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "AthleteDiscovery_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE
);

-- Public reads never seed or mutate configuration. Existing sports are reused.
